/* From Uiverse.io by shlomo20 - Tags: gradient, card, hover, gradients */
.__UIV_SCOPE__ .cards {
  position: relative;
}

.__UIV_SCOPE__ .card {
  z-index: 1;
  position: absolute;
  width: 254px;
  height: 190px;
  border-radius: 10px;
  transition: all .5s ease-out;
  overflow: hidden;
  transform: translateX(0px) translateY(0px) perspective(905px) rotateX(0deg) rotateY(0deg) rotateZ(-8deg);
}

.__UIV_SCOPE__ .card.one {
  top: -120px;
  left: -150px;
  background: linear-gradient(180deg, #FF0055 0%, #000066 100%);
}

.__UIV_SCOPE__ .card.two {
  top: -95px;
  left: -125px;
  background: linear-gradient(180deg, #fa00ff 0%, #01f998 99%);
}

.__UIV_SCOPE__ .card.three {
  top: -70px;
  left: -100px;
  background: linear-gradient(180deg, #c0f901 0%, #fa00ff 100%);
}

.__UIV_SCOPE__ .card:hover {
  z-index: 4;
  transform: perspective(1000px) rotateX(0deg) rotateY(0deg) rotateZ(0deg) !important;
  transition: all .5s ease-out;
}

.__UIV_SCOPE__ .cardDetails {
  width: 55%;
  height: 100%;
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-end;
  background: rgba(0,0,0,0.8);
  transition: .5s;
  transform-origin: left;
  transform: perspective(2000px) rotateY(-90deg);
}

.__UIV_SCOPE__ .card:hover .cardDetails {
  transform: perspective(2000px) rotateY(0deg);
}

.__UIV_SCOPE__ .cardDetailsHaeder {
  font-weight: 600;
  color: #edb899;
}

.__UIV_SCOPE__ .cardDetailsButton {
  padding: 3px 6px;
  border-radius: 25px;
  background-color: #edb899;
  color: #000;
  font-weight: 600;
}
